import { useState, useEffect, useCallback, useLayoutEffect } from 'react';
import Button from 'react-bootstrap/Button';

import 'bootstrap/dist/css/bootstrap.min.css';
import './App.css';

import { HashRouter, Route, Routes, Link, useLocation } from 'react-router-dom';
import { useMediaQuery } from 'react-responsive';
import { Squash as Hamburger } from 'hamburger-react';


import AppIndex from './AppIndex';
import Nakasendo from './nakasendo/nakasendo_index';
import NakasendoPrologue from './nakasendo/nakasendoPrologue';
import NakasendoDay01 from './nakasendo/nakasendoDay01';
import NakasendoDay02 from './nakasendo/nakasendoDay02';
import NakasendoDay03 from './nakasendo/nakasendoDay03';
import NakasendoDay04 from './nakasendo/nakasendoDay04';
import Nikkokaido from './nikkokaido/nikkokaido_index';
import Koshukaido from './koshukaido/koshukaido_index';
import Oshukaido from './oshukaido/oshukaido_index';
import Tokaido from './tokaido/tokaido_index';
import Okunohosomichi from './okunohosomichi/okunohosomichi_index';
import Testimonials from './Testimonials';
import NeedToKnowTerminology from './NeedToKnowTerminology';


// Wrapper component - MUST be defined outside App to prevent remounts on state changes
const Wrapper = ({ children }) => {
  const location = useLocation();

  useLayoutEffect(() => {
    // Scroll to the top of the page when the route changes
    window.scrollTo({ top: 0, left: 0, behavior: 'instant' });
  }, [location.pathname]);

  return children;
};

 
function App() {

  const isMobile = useMediaQuery({ query: '(max-width: 768px)' });
  const isLandscape = useMediaQuery({ query: '(orientation: landscape)' });

  const [mobileIsVisible, setMobileIsVisible] = useState(false);
  const [desktopIsVisible, setDesktopIsVisible] = useState(false);

  const [screenWidth, setScreenWidth] = useState(window.innerWidth);

  const handleWindowResize = useCallback(event => {
    setScreenWidth(window.innerWidth);
  }, []);


  useEffect(() => {

    window.addEventListener('resize', handleWindowResize);
    return () => {
      window.removeEventListener('resize', handleWindowResize);
    };
  }, [handleWindowResize]);


  const sidebarData = [
    { 
      name: 'Home',
      path: '/',
      icon: '',
      cName: 'MobileLinkText',
      dName: 'DesktopLinkText',
    },
    {
      name: 'Need to Know Terminology',
      path: '/Need-to-know-terminology',
      icon: '',
      cName: 'MobileLinkText',
      dName: 'DesktopLinkText',
    },
    {
      name: 'The Nakasendo',
      path: '/Nakasendo',
      icon: '',
      cName: 'MobileLinkText',
      dName: 'DesktopLinkText',
    },
    {
      name: 'The Nikko Kaido',
      path: '/Nikkokaido',
      icon: '',
      cName: 'MobileLinkText',
      dName: 'DesktopLinkText',
    },
    {
      name: 'The Koshu Kaido',
      path: '/Koshukaido',
      icon: '',
      cName: 'MobileLinkText',
      dName: 'DesktopLinkText',
    },
    {
      name: 'The Oshu Kaido',
      path: '/Oshukaido',
      icon: '',
      cName: 'MobileLinkText',
      dName: 'DesktopLinkText',
    },
    {
      name: 'The Tokaido',
      path: '/Tokaido',
      icon: '',
      cName: 'MobileLinkText',
      dName: 'DesktopLinkText',
    },
    {
      name: 'Oku no Hosomichi',
      path: '/Okunohosomichi',
      icon: '',
      cName: 'MobileLinkText',
      dName: 'DesktopLinkText',
    },
    {
      name: 'Walk with Us - Testimonials',
      path: '/Testimonials',
      icon: '',
      cName: 'MobileLinkText',
      dName: 'DesktopLinkText',
    },
  ];

  const scrollTop = () => {
    window.scrollTo(0, 0)
  }

  const handleMobileMenuLinkClick = () => {
    let updateMobileIsVisible = !mobileIsVisible;
    setMobileIsVisible(updateMobileIsVisible);
  }

  return (
    <div className="App">
      <HashRouter>
        <Wrapper>
          {isMobile && !isLandscape ?
            <div className="MobileHeader">
              <div className="MobileTitle">
                The Brokaido
              </div>
              <div className="MobileMenu" >
                <Hamburger rounded duration={0.4} size={40} toggled={mobileIsVisible} toggle={setMobileIsVisible} />
              </div>
              {/* This is the mobile sidebar! */}
              <div className={mobileIsVisible ? "MobileHeaderLinks active": "MobileHeaderLinks"}>
                <nav>
                  <ul onClick={handleMobileMenuLinkClick}>
                    {sidebarData.map((item, idx) => (
                      <li key={idx} className={item.cName}>
                        <Link to={item.path}>
                          <span style={{ marginRight: "9px" }}>{item.icon}</span>
                          <span>{item.name}</span>
                        </Link>
                      </li>
                    ))}
                  </ul>
                </nav>
              </div>
              {/* End Mobile Sidebar */}
            </div>
            :
            <div className="Header">
              <div className="HeaderWashi">
                <div className="HeaderUkiyoe">
                  {(screenWidth > 1275)
                    ?
                    <img className="UkiyoeImage" src={require('./assets/HeaderBG65.png')} alt="ukiyoe" />
                    :
                    ((screenWidth < 976) && (window.screen.availHeight > window.screen.availWidth))
                      ?
                      <img className="UkiyoeImage" src={require('./assets/HeaderBG65_stubbier.png')} alt="ukiyoe" />
                      :
                      <img className="UkiyoeImage" src={require('./assets/HeaderBG65_stubby.png')} alt="ukiyoe" />
                  }
                  <div className="HeaderUkiyoeContents">
                    <div className="HeaderButtonContainerLeft">
                      <Link to='/Need-to-know-terminology'>
                        <Button className="HeaderNavigationButtons" variant="outline-primary" onClick={scrollTop}>
                          {screenWidth < 835
                            ?
                            "Terminology"
                            :
                            "Need-to-know Terminology"
                          } </Button>
                      </Link>
                      <span>
                        <Button className="HeaderNavigationButtons" variant="outline-primary"> The Roads </Button>
                      </span>
                    </div>
                    <div className="HeaderTitle">
                      The Brokaido
                    </div>
                    <div className="HeaderButtonContainerRight" style={{ backgroundColor: "transparent", color: "white" }}>
                      <Link>
                        <Button className="HeaderNavigationButtons" variant="outline-primary"> Other </Button>
                      </Link>
                      <Link to='/Testimonials'>
                        <Button className="HeaderNavigationButtons" variant="outline-primary" onClick={scrollTop}> Testimonials </Button>
                      </Link>
                    </div>
                  </div>
                </div>
              </div>
              {/* <div className="HeaderBorder" />  */}
              {/* Desktop Menu 1 */}
              <div className={desktopIsVisible ? "DesktopRoadsHeaderLinks active" : "DesktopRoadsHeaderLinks"}>
                <nav>
                  <ul>
                    {sidebarData.map((item, idx) => (
                      <li key={idx} className={item.dName}>
                        <Link to={item.path}>
                          <span style={{ marginRight: "9px" }}>{item.icon}</span>
                          <span>{item.name}</span>
                        </Link>
                      </li>
                    ))}
                  </ul>
                </nav>
              </div>
              {/* End Desktop Menu 1 */}
            </div>


          }

          <div className="AppBody">
            <Routes>
              <Route path='/' element={<AppIndex />} />
              <Route path='/Nakasendo'>
                <Route index element={<Nakasendo />} />
                <Route path='Prologue' element={<NakasendoPrologue />} />
                <Route path='Day01' element={<NakasendoDay01 />} />
                <Route path='Day02' element={<NakasendoDay02 />} />
                <Route path='Day03' element={<NakasendoDay03 />} />
                <Route path='Day04' element={<NakasendoDay04 />} />
              </Route>
              <Route path='/Tokaido' element={<Tokaido />} />
              <Route path='/Nikkokaido' element={<Nikkokaido />} />
              <Route path='/Koshukaido' element={<Koshukaido />} />
              <Route path='/Oshukaido' element={<Oshukaido />} />
              <Route path='/Okunohosomichi' element={<Okunohosomichi />} />
              <Route path='/Need-to-know-terminology' element={<NeedToKnowTerminology />} />
              <Route path='/Testimonials' element={<Testimonials />} />
            </Routes>
          </div>
        </Wrapper>
      </HashRouter>
    </div>
  );
}

export default App;
